right_code.class:
// Preferred idiom: Copy Constructor or Copy Factory
import java.util.Arrays;

public class Stack {
    private Object[] elements;
    private int size;

    public Stack() { this.elements = new Object[16]; this.size = 0; }

    // Copy constructor: clean, safe, no Cloneable magic, doesn't bypass constructors!
    public Stack(Stack other) {
        this.size = other.size;
        this.elements = other.elements.clone(); // Array clone is safe and idiomatically sanctioned
    }

    // Copy factory
    public static Stack newInstance(Stack other) {
        return new Stack(other);
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        Stack s1 = new Stack();
        Stack s2 = new Stack(s1); // Safe, independent deep copy
        Stack s3 = Stack.newInstance(s1);
    }
}
